// Tests for the screen helpers: "Find a measure" finds every row by the name it shows, the crew's own mission and
// its day count, and the chart's limit names that wrap instead of being cut. Pure functions, no browser needed.
// Run: node --test tests/screens.test.js. Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { CELLS } from '../src/config.js';
import { KIND } from '../src/engine.js';
import { INSPIRATION4 } from '../src/inspiration4.js';
import { shortLabel, WORDS, findText, findHit, normalFind } from '../src/find.js';
import { missionProblem, readMission, missionTimes, flightDay, missionDay, MISSION_RULES } from '../src/mission.js';
import { wrapWords } from '../src/history-view.js';

// The rows of All measures, as src/crew.js builds them: the person's measures (numbers and own answers, not the
// private ones), images and tracings, the camera, and the cabin air.
const shown = CELLS.filter((c) => (c.kind === KIND.NUMBER || c.kind === KIND.SELF || c.kind === KIND.COMPLEX || c.indicator === 'camera') && !c.private && c.section !== 'tests');
const rowText = (c) => findText({ name: c.indicator === 'camera' ? 'Camera' : shortLabel(c), label: c.label, words: WORDS[c.indicator] });

test('every measure is found by the name on its row and by its full name, in any case and spacing', () => {
  assert.ok(shown.length >= 30, `${shown.length} rows`);
  for (const c of shown) {
    const name = c.indicator === 'camera' ? 'Camera' : shortLabel(c);
    assert.ok(findHit(name, rowText(c)), `${c.indicator}: "${name}"`);
    assert.ok(findHit(c.label, rowText(c)), `${c.indicator}: "${c.label}"`);
    assert.ok(findHit(`  ${name.toUpperCase()}  `, rowText(c)), `${c.indicator}: upper case with spaces`);
  }
  for (const [name, ind] of [['Body temperature', 'temp'], ['Blood oxygen', 'spo2'], ['Fasting glucose', 'glucose'], ['Reaction time', 'reaction'], ['Eye pressure', 'eyePressure'], ['Hearing threshold', 'hearing'], ['Cabin CO2', 'co2'], ['Cabin pressure', 'cabinPressure']]) {
    const c = CELLS.find((x) => x.indicator === ind);
    assert.ok(findHit(name, rowText(c)), name);
  }
});

test('the everyday words still work, and a word that names nothing finds nothing', () => {
  const glucose = CELLS.find((c) => c.indicator === 'glucose');
  assert.ok(findHit('sugar', rowText(glucose)));
  assert.ok(findHit('', rowText(glucose)), 'an empty search shows everything');
  assert.equal(shown.filter((c) => findHit('zzzz', rowText(c))).length, 0);
  // The walks of the screen rely on these: "reaction" finds only the reaction test, "oct" finds the OCT rows first.
  assert.deepEqual(shown.filter((c) => findHit('reaction', rowText(c))).map((c) => c.indicator), ['reaction']);
  assert.ok(shown.filter((c) => findHit('oct', rowText(c))).every((c) => /oct/i.test(c.indicator)));
  assert.equal(normalFind('Can’t  Find'), "can't find");
});

test('every Inspiration4 blood value is found by its own name', () => {
  const names = new Set();
  for (const s of Object.values(INSPIRATION4.subjects)) for (const panel of Object.values(s.panels)) for (const a of panel) names.add(a.nameEn || a.name);
  assert.ok(names.size >= 30, `${names.size} names`);
  for (const n of names) assert.ok(findHit(n, findText({ name: n })), n);
  assert.ok(findHit('glucose', findText({ name: 'Glucose' })));
});

// ---------- the crew's own mission ----------
test('a mission needs real launch and landing dates, landing not before launch, and a short name', () => {
  assert.equal(missionProblem({ name: 'HERA C7', launch: '2026-11-01', landing: '2026-12-15' }), null);
  assert.match(missionProblem({ launch: '', landing: '2026-12-15' }), /launch/);
  assert.match(missionProblem({ launch: '2026-11-01', landing: '2026-02-31' }), /landing/);
  assert.match(missionProblem({ launch: '2026-11-01', landing: '2026-10-01' }), /before the launch/);
  assert.match(missionProblem({ name: 'x'.repeat(MISSION_RULES.nameMax + 1), launch: '2026-11-01', landing: '2026-11-02' }), /at most/);
  assert.deepEqual(readMission({ name: ' HERA C7 ', launch: '2026-11-01', landing: '2026-12-15', extra: 1 }), { name: 'HERA C7', launch: '2026-11-01', landing: '2026-12-15' });
  assert.equal(readMission({ launch: 'soon', landing: '2026-12-15' }), null);
  assert.equal(readMission(null), null);
});

test('the day count: launch day is flight day 1, L- before launch, R+ after landing, by GMT days', () => {
  const m = { name: 'HERA C7', launch: '2026-11-01', landing: '2026-12-15' };
  assert.deepEqual(flightDay(m, Date.parse('2026-11-01T00:00:00Z')).short, 'FD 1');
  assert.deepEqual(flightDay(m, Date.parse('2026-11-15T23:59:00Z')).short, 'FD 15');
  assert.equal(flightDay(m, Date.parse('2026-12-15T22:00:00Z')).short, 'FD 45', 'the landing day is the last flight day');
  assert.equal(flightDay(m, Date.parse('2026-10-29T08:00:00Z')).short, 'L-3');
  assert.equal(flightDay(m, Date.parse('2026-10-29T08:00:00Z')).words, '3 days to launch');
  assert.equal(flightDay(m, Date.parse('2026-12-16T01:00:00Z')).short, 'R+1');
  assert.equal(flightDay(m, Date.parse('2026-12-16T01:00:00Z')).words, '1 day after landing');
  assert.equal(flightDay(null, Date.now()), null, 'no mission, no flight day');
});

test('the mission as the screen uses it: midday GMT dates, now as today, the dates in words', () => {
  const t = missionTimes({ name: '', launch: '2026-11-01', landing: '2026-12-15' }, Date.parse('2026-11-15T09:00:00Z'));
  assert.equal(t.name, MISSION_RULES.defaultName);
  assert.equal(t.launch, '2026-11-01T12:00:00Z');
  assert.equal(t.landing, '2026-12-15T12:00:00Z');
  assert.equal(t.today, '2026-11-15T09:00:00.000Z');
  assert.equal(missionDay('2026-06-01'), '1 Jun 2026');
});

// ---------- the chart's limit names ----------
test('a long limit name wraps at spaces into lines that fit, and nothing of it is lost', () => {
  const measure = (s) => s.length * 8.4; // 14 px monospace
  const label = 'Earliest indication of SANS: 20 µm (draft)';
  const lines = wrapWords(label, 215, measure);
  assert.ok(lines.length >= 2);
  for (const l of lines) assert.ok(measure(l) <= 215 || !l.includes(' '), l);
  assert.equal(lines.join(' '), label);
  assert.ok(lines[lines.length - 1].endsWith('(draft)'));
  assert.deepEqual(wrapWords('NASA career limit', 400, measure), ['NASA career limit']);
  assert.deepEqual(wrapWords('', 100, measure), []);
});
